/* VECTOR: a 3-component float vector (12 bytes, unaligned): positions, directions and Euler angles in data records.
   Layout from src/game/core/math/vec/PosSmooth.cpp (34 copies in Lilly ports) */
struct VECTOR
{
    float x, y, z;
};

/* RGBA: an 8-bit-per-channel colour; assignment from an int unpacks 0xRRGGBBAA.
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (13 copies in Lilly ports) */
struct RGBA
{
    uchar red;    /* red, 0..255 */
    uchar green;    /* green, 0..255 */
    uchar blue;    /* blue, 0..255 */
    uchar alpha;    /* alpha (opacity), 0..255 */
    // Set the color from a packed 0xRRGGBBAA word.
    inline void operator=(const int rgba)
    {
        red = (rgba >> 24) & 0xFF;
        green = (rgba >> 16) & 0xFF;
        blue = (rgba >> 8) & 0xFF;
        alpha = rgba & 0xFF;
    }
};

/* VECTOR4: a 16-byte aligned 4-component float vector (one VU0 register); w is often padding or a homogeneous 1.
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (28 copies in Lilly ports) */
struct VECTOR4
{
    float x, y, z, w;
} __attribute__((aligned(16)));

/* MATRIX4: a 16-byte aligned 4x4 float matrix (four rows of four floats, one VU0 register per row).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (32 copies in Lilly ports) */
struct MATRIX4
{
	float mat[4][4];
} __attribute__((aligned(16)));

/* MATRIX3: a 3x3 rotation matrix stored as three 16-byte aligned rows (the fourth float of each row is padding).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (29 copies in Lilly ports) */
struct MATRIX3
{
	float mat[3][4];
} __attribute__((aligned(16)));

/* SMP: smoothing parameters for a value that chases a target: the speed used far from / near the target and the time
   constant (inferred from Sly 1 SmoothValue).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (4 copies in Lilly ports) */
struct SMP
{
    float fastSpeed; /* speed (units/s) when far from the target */
    float slowSpeed; /* speed (units/s) when close to the target */
    float fastDuration; /* time scale (s) over which the fast speed applies */
};

/* SMPA: SMP with an acceleration limit: smoothing parameters for a value with a capped change of speed (Sly 1 SMPA).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (16 copies in Lilly ports) */
struct SMPA
{
    float fastSpeed; /* speed (units/s) when far from the target */
    float slowSpeed; /* speed (units/s) when close to the target */
    float fastDuration; /* time scale (s) over which the fast speed applies */
    float maxSpeedChange; /* largest change of speed per second */
};

/* CLQ: a quadratic curve c0 + c1*x + c2*x^2 read from level data (Sly 1 CLQ, evaluated by GEvaluateClq).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (24 copies in Lilly ports) */
struct CLQ
{
    union
    {
        struct
        {
            float g0, g1, g2, unused;
        };
        float coefficients[4]; /* the same coefficients as an array */
    };
};

/* LM: a float range [minValue, maxValue] ("limits"), read from level data and used to clamp or randomise values.
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (24 copies in Lilly ports) */
struct LM
{
	float minValue, maxValue; /* lower and upper bound */
};

